  + address : string
}

class Order {
  + totalCost : float
  + estimatedDeliveryTime : time
  + status : string
}

class Dish {
  + name : string
  + preparationTime : time
}

class Kitchen {
  + currentWorkload : int
}

class DeliveryDepartment {
}

